insert into public.impression_contacts(id,name,label,avatar) values ('participant-alfaz','Alfaz','Group member','A') on conflict(id) do update set name=excluded.name;
insert into public.impression_messages(contact_id,sender_id,body,created_at) values ('group','participant-alfaz','Jaysha is genuinely one of the most caring people I know, and becoming friends with her was honestly one of the best decisions I’ve ever made. Isne mujhe bohot kuch sikhaya hai, especially kaise behave karna chahiye 🤣😭 and she’s always there for us whenever we need her. Baaki maine duniya mein 500 khoobsurat ladkiyan dekhi thi, phir Jaysha se mila aur woh number 500 hi hai abhi tak🤣','2026-10-31T11:00:00+05:30'::timestamptz + interval '2 seconds');
