insert into public.impression_contacts(id,name,label,avatar) values ('participant-abhay','Abhay','Group member','A') on conflict(id) do update set name=excluded.name;
insert into public.impression_messages(contact_id,sender_id,body,created_at) values ('group','participant-abhay','Hello Jaysha, yeh aapke badiya se boyfriend ne bola hai aapke liyeh kuch likhne ko. Wesse toh sach batao mann nhi hai because aapne aur Shreya ne jo baatei aur cheeze kari thi woh bachelor''s party pe 🥲 But on the other hand mere help bhi kari Nishka ki shadi pe Shreya ki family k saath chill karne mei ;) toh thode bahut theek thak ho aap :P But chalo mazak masti chor kar you''re one of the nicest person I''ve ever met and I''m blessed that Shreya has you as her best friend. But ek baat suno aap, Shreya ko yeh cute gifts dena band karo bhai, phir aap jeet jaate ho har saal cute waale section mei and no hugs for the both of you 🔪 ! Arey haan aapka toh birthday bhi hai naa :P Happy birthday :P','2026-10-31T11:00:00+05:30'::timestamptz + interval '5 seconds');
insert into public.impression_contacts(id,name,label,avatar) values ('participant-apoorv','Apoorv','Group member','A') on conflict(id) do update set name=excluded.name;
insert into public.impression_messages(contact_id,sender_id,body,created_at) values ('group','participant-apoorv','Jaysha, you are special because ordinary people don''t go to the gym at 2 or 3 o''clock in the afternoon, but you do. Today is your special day, and I hope at least today Uncle & Aunty don''t ditch you to be with Leo while they go on a date. If you feel “elevated” today, you are allowed to do so, with the blessing of the Apoorv Singh, of course. Can’t wait to see your father.','2026-10-31T11:00:00+05:30'::timestamptz + interval '6 seconds');
insert into public.impression_contacts(id,name,label,avatar) values ('participant-siddharth','Siddharth','Group member','S') on conflict(id) do update set name=excluded.name;
